1	// Pre-push OPF rewrite for the git-refs checkpoint backend, the sibling of
2	// manual_commit_opf_rewrite.go's entire/checkpoints/v1 rewrite. Both run the
3	// OPF-augmented redaction once per push; only discovery and ref update differ.
4	package strategy
5	
6	import (
7		"context"
8		"errors"
9		"fmt"
10		"slices"
11	
12		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
13		"github.com/entireio/cli/cmd/entire/cli/trailers"
14		"github.com/entireio/cli/redact"
15		"github.com/go-git/go-git/v6"
16		"github.com/go-git/go-git/v6/plumbing"
17		"github.com/go-git/go-git/v6/plumbing/object"
18	)
19	
20	// RewriteQueuedCheckpointRefsWithOPF re-redacts the checkpoint refs awaiting
21	// push with OPF, rebuilds every un-applied commit on each as a commit carrying
22	// Entire-OPF-Applied: true, and points the ref at the new tip. Idempotent: a
23	// ref whose tip already carries the trailer is left byte-identical.
24	//
25	// Discovery is the push-discovery queue rather than a local-vs-remote diff: it
26	// already names exactly the refs this push will carry, so there is no
27	// merge-base or divergence analysis. Within a ref, pushing it carries its whole
28	// unpushed ancestry, so the walk covers every commit back to the first one
29	// already carrying the trailer (unappliedAncestry) — bounded by the same
30	// resolveBootstrapLimit the v1 path uses.
31	//
32	// Caller checks redact.OPFEnabled() and skips this when OPF is off. Returns
33	// the same error taxonomy as RewriteUnpushedV1WithOPF; the caller fails closed
34	// by withholding the flush (see prePushCheckpointRefs).
35	func RewriteQueuedCheckpointRefsWithOPF(ctx context.Context, repo *git.Repository) error {
36		queue, err := checkpoint.PushQueueForRepo(ctx, repo)
37		if err != nil {
38			return fmt.Errorf("resolve push queue: %w", err)
39		}
40		// Peek, not Drain: flushCheckpointRefsQueue owns draining and pruning.
41		queued, err := queue.Peek()
42		if err != nil {
43			return fmt.Errorf("peek push queue: %w", err)
44		}
45		if len(queued) == 0 {
46			return nil
47		}
48	
49		// Both up-front fail-closed gates, in the same order as the v1 rewrite, so
50		// a misconfigured category set surfaces config remediation rather than
51		// "verify your OPF install".
52		if redact.OPFMisconfiguredNoCategories() {
53			return &OPFNoCategoriesError{}
54		}
55		if redact.OPFBreakerTripped() {
56			return &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand()}
57		}
58	
59		// Pass 1: collect every redactable blob from every un-applied commit on every
60		// queued ref, bounding raw bytes in memory exactly as the v1 collect pass
61		// does — cumulatively across the whole flush, not per ref.
62		type pendingCommit struct {
63			commit *object.Commit
64			// blobs and paths are parallel; startIdx is this commit's offset into
65			// the global redacted slice.
66			blobs    []redact.NamedBlob
67			paths    []string
68			startIdx int
69		}
70		type pendingRef struct {
71			ref plumbing.ReferenceName
72			old plumbing.Hash
73			// base is the parent the deepest rewritten commit keeps.
74			base    plumbing.Hash
75			commits []pendingCommit // ancestor-first
76		}
77		var globalBlobs []redact.NamedBlob
78		pendings := make([]pendingRef, 0, len(queued))
79		rawCap := scaleBatchLimit(resolveBatchLimit(), rawByteCapMultiplier)
80		bootstrapLimit := resolveBootstrapLimit()
81		var rawBytesSoFar int
82		// Stale entries (refs no longer present locally) are skipped, not pruned:
83		// the queue belongs to the flush.
84		existing, _ := partitionLocalRefs(repo, queued)
85		for _, refName := range existing {
86			ref, refErr := repo.Reference(refName, true)
87			if refErr != nil {
88				if errors.Is(refErr, plumbing.ErrReferenceNotFound) {
89					continue
90				}
91				return fmt.Errorf("resolve checkpoint ref %s: %w", refName, refErr)
92			}
93			chain, base, walkErr := unappliedAncestry(repo, ref.Hash())
94			if walkErr != nil {
95				return fmt.Errorf("walk ancestry of %s: %w", refName, walkErr)
96			}
97			if len(chain) == 0 {
98				continue
99			}
100			if len(chain) > bootstrapLimit {
101				return &BootstrapTooLargeError{Count: len(chain), Limit: bootstrapLimit}
102			}
103			pr := pendingRef{ref: refName, old: ref.Hash(), base: base}
104			for _, c := range chain {
105				tree, treeErr := repo.TreeObject(c.TreeHash)
106				if treeErr != nil {
107					return fmt.Errorf("load tree for %s: %w", c.Hash.String()[:7], treeErr)
108				}
109				pc := pendingCommit{commit: c, startIdx: len(globalBlobs)}
110				if err := collectTreeBlobs(repo, tree, "", &pc.blobs, &pc.paths); err != nil {
111					return fmt.Errorf("collect blobs %s: %w", c.Hash.String()[:7], err)
112				}
113				for _, b := range pc.blobs {
114					rawBytesSoFar += len(b.Content)
115				}
116				if rawBytesSoFar > rawCap {
117					return &OPFRawBytesTooLargeError{RawBytes: rawBytesSoFar, Limit: rawCap}
118				}
119				globalBlobs = append(globalBlobs, pc.blobs...)
120				pr.commits = append(pr.commits, pc)
121			}
122			pendings = append(pendings, pr)
123		}
124		if len(pendings) == 0 {
125			return nil
126		}
127	
128		// Pass 2: enforce the leaf-byte cap, then make exactly ONE OPF shell-out
129		// for the whole flush.
130		var globalRedacted [][]byte
131		if len(globalBlobs) > 0 {
132			leafBytes := redact.SumProseLeafBytes(globalBlobs)
133			if limit := resolveBatchLimit(); leafBytes > limit {
134				return &OPFBatchTooLargeError{LeafBytes: leafBytes, Limit: limit}
135			}
136			globalRedacted, err = redact.BatchBytesWithPrivacyFilter(ctx, globalBlobs)
137			if err != nil {
138				if errors.Is(err, redact.ErrOPFNoEnabledCategories) {
139					return &OPFNoCategoriesError{}
140				}
141				return &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand(), Cause: err}
142			}
143		}
144	
145		// Pass 3: rebuild every commit before touching any ref, so a failure
146		// part-way through leaves every ref where it was. Each ref's chain is
147		// replayed ancestor→tip, so the rewritten parent carries into the next
148		// commit and the deepest one keeps the boundary parent.
149		rebuilt := make([]plumbing.Hash, len(pendings))
150		for i, pr := range pendings {
151			parent := pr.base
152			for _, pc := range pr.commits {
153				redactedByPath := make(map[string][]byte, len(pc.blobs))
154				for j, path := range pc.paths {
155					redactedByPath[path] = globalRedacted[pc.startIdx+j]
156				}
157				newHash, rebuildErr := rebuildCheckpointCommit(ctx, repo, pc.commit, parent, redactedByPath)
158				if rebuildErr != nil {
159					return fmt.Errorf("rebuild checkpoint commit %s on %s: %w", pc.commit.Hash.String()[:7], pr.ref, rebuildErr)
160				}
161				parent = newHash
162			}
163			rebuilt[i] = parent
164		}
165	
166		// CAS each ref: a concurrent write that advanced a checkpoint ref during
167		// the rewrite must not be clobbered by our stale rebuild.
168		for i, pr := range pendings {
169			if err := repo.Storer.CheckAndSetReference(
170				plumbing.NewHashReference(pr.ref, rebuilt[i]),
171				plumbing.NewHashReference(pr.ref, pr.old),
172			); err != nil {
173				return fmt.Errorf("update checkpoint ref %s: %w", pr.ref, err)
174			}
175		}
176		return nil
177	}
178	
179	// unappliedAncestry walks first parents back from a checkpoint ref's tip and
180	// returns the commits that do not carry the OPF trailer, ancestor-first, plus
181	// the parent the deepest one keeps: the trailered commit the walk stopped at,
182	// or zero at a root. Checkpoint refs are a single-parent chain, so the first
183	// parent is the whole history.
184	func unappliedAncestry(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, plumbing.Hash, error) {
185		var chain []*object.Commit
186		base := plumbing.ZeroHash
187		for h := tip; !h.IsZero(); {
188			c, err := repo.CommitObject(h)
189			if err != nil {
190				return nil, plumbing.ZeroHash, fmt.Errorf("load commit %s: %w", h.String()[:7], err)
191			}
192			if trailers.HasOPFApplied(c.Message) {
193				base = h
194				break
195			}
196			chain = append(chain, c)
197			if len(c.ParentHashes) == 0 {
198				break
199			}
200			h = c.ParentHashes[0]
201		}
202		slices.Reverse(chain)
203		return chain, base, nil
204	}
