// Pre-push OPF rewrite for the git-refs checkpoint backend, the sibling of
// manual_commit_opf_rewrite.go's entire/checkpoints/v1 rewrite. Both run the
// OPF-augmented redaction once per push; only discovery and ref update differ.
package strategy

import (
	"context"
	"errors"
	"fmt"
	"slices"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
	"github.com/entireio/cli/redact"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// RewriteQueuedCheckpointRefsWithOPF re-redacts the checkpoint refs awaiting
// push with OPF, rebuilds every un-applied commit on each as a commit carrying
// Entire-OPF-Applied: true, and points the ref at the new tip. Idempotent: a
// ref whose tip already carries the trailer is left byte-identical.
//
// Discovery is the push-discovery queue rather than a local-vs-remote diff: it
// already names exactly the refs this push will carry, so there is no
// merge-base or divergence analysis. Within a ref, pushing it carries its whole
// unpushed ancestry, so the walk covers every commit back to the first one
// already carrying the trailer (unappliedAncestry) — bounded by the same
// resolveBootstrapLimit the v1 path uses.
//
// Caller checks redact.OPFEnabled() and skips this when OPF is off. Returns
// the same error taxonomy as RewriteUnpushedV1WithOPF; the caller fails closed
// by withholding the flush (see prePushCheckpointRefs).
func RewriteQueuedCheckpointRefsWithOPF(ctx context.Context, repo *git.Repository) error {
	queue, err := checkpoint.PushQueueForRepo(ctx, repo)
	if err != nil {
		return fmt.Errorf("resolve push queue: %w", err)
	}
	// Peek, not Drain: flushCheckpointRefsQueue owns draining and pruning.
	queued, err := queue.Peek()
	if err != nil {
		return fmt.Errorf("peek push queue: %w", err)
	}
	if len(queued) == 0 {
		return nil
	}

	// Both up-front fail-closed gates, in the same order as the v1 rewrite, so
	// a misconfigured category set surfaces config remediation rather than
	// "verify your OPF install".
	if redact.OPFMisconfiguredNoCategories() {
		return &OPFNoCategoriesError{}
	}
	if redact.OPFBreakerTripped() {
		return &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand()}
	}

	// Pass 1: collect every redactable blob from every un-applied commit on every
	// queued ref, bounding raw bytes in memory exactly as the v1 collect pass
	// does — cumulatively across the whole flush, not per ref.
	type pendingCommit struct {
		commit *object.Commit
		// blobs and paths are parallel; startIdx is this commit's offset into
		// the global redacted slice.
		blobs    []redact.NamedBlob
		paths    []string
		startIdx int
	}
	type pendingRef struct {
		ref plumbing.ReferenceName
		old plumbing.Hash
		// base is the parent the deepest rewritten commit keeps.
		base    plumbing.Hash
		commits []pendingCommit // ancestor-first
	}
	var globalBlobs []redact.NamedBlob
	pendings := make([]pendingRef, 0, len(queued))
	rawCap := scaleBatchLimit(resolveBatchLimit(), rawByteCapMultiplier)
	bootstrapLimit := resolveBootstrapLimit()
	var rawBytesSoFar int
	// Stale entries (refs no longer present locally) are skipped, not pruned:
	// the queue belongs to the flush.
	existing, _ := partitionLocalRefs(repo, queued)
	for _, refName := range existing {
		ref, refErr := repo.Reference(refName, true)
		if refErr != nil {
			if errors.Is(refErr, plumbing.ErrReferenceNotFound) {
				continue
			}
			return fmt.Errorf("resolve checkpoint ref %s: %w", refName, refErr)
		}
		chain, base, walkErr := unappliedAncestry(repo, ref.Hash())
		if walkErr != nil {
			return fmt.Errorf("walk ancestry of %s: %w", refName, walkErr)
		}
		if len(chain) == 0 {
			continue
		}
		if len(chain) > bootstrapLimit {
			return &BootstrapTooLargeError{Count: len(chain), Limit: bootstrapLimit}
		}
		pr := pendingRef{ref: refName, old: ref.Hash(), base: base}
		for _, c := range chain {
			tree, treeErr := repo.TreeObject(c.TreeHash)
			if treeErr != nil {
				return fmt.Errorf("load tree for %s: %w", c.Hash.String()[:7], treeErr)
			}
			pc := pendingCommit{commit: c, startIdx: len(globalBlobs)}
			if err := collectTreeBlobs(repo, tree, "", &pc.blobs, &pc.paths); err != nil {
				return fmt.Errorf("collect blobs %s: %w", c.Hash.String()[:7], err)
			}
			for _, b := range pc.blobs {
				rawBytesSoFar += len(b.Content)
			}
			if rawBytesSoFar > rawCap {
				return &OPFRawBytesTooLargeError{RawBytes: rawBytesSoFar, Limit: rawCap}
			}
			globalBlobs = append(globalBlobs, pc.blobs...)
			pr.commits = append(pr.commits, pc)
		}
		pendings = append(pendings, pr)
	}
	if len(pendings) == 0 {
		return nil
	}

	// Pass 2: enforce the leaf-byte cap, then make exactly ONE OPF shell-out
	// for the whole flush.
	var globalRedacted [][]byte
	if len(globalBlobs) > 0 {
		leafBytes := redact.SumProseLeafBytes(globalBlobs)
		if limit := resolveBatchLimit(); leafBytes > limit {
			return &OPFBatchTooLargeError{LeafBytes: leafBytes, Limit: limit}
		}
		globalRedacted, err = redact.BatchBytesWithPrivacyFilter(ctx, globalBlobs)
		if err != nil {
			if errors.Is(err, redact.ErrOPFNoEnabledCategories) {
				return &OPFNoCategoriesError{}
			}
			return &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand(), Cause: err}
		}
	}

	// Pass 3: rebuild every commit before touching any ref, so a failure
	// part-way through leaves every ref where it was. Each ref's chain is
	// replayed ancestor→tip, so the rewritten parent carries into the next
	// commit and the deepest one keeps the boundary parent.
	rebuilt := make([]plumbing.Hash, len(pendings))
	for i, pr := range pendings {
		parent := pr.base
		for _, pc := range pr.commits {
			redactedByPath := make(map[string][]byte, len(pc.blobs))
			for j, path := range pc.paths {
				redactedByPath[path] = globalRedacted[pc.startIdx+j]
			}
			newHash, rebuildErr := rebuildCheckpointCommit(ctx, repo, pc.commit, parent, redactedByPath)
			if rebuildErr != nil {
				return fmt.Errorf("rebuild checkpoint commit %s on %s: %w", pc.commit.Hash.String()[:7], pr.ref, rebuildErr)
			}
			parent = newHash
		}
		rebuilt[i] = parent
	}

	// CAS each ref: a concurrent write that advanced a checkpoint ref during
	// the rewrite must not be clobbered by our stale rebuild.
	for i, pr := range pendings {
		if err := repo.Storer.CheckAndSetReference(
			plumbing.NewHashReference(pr.ref, rebuilt[i]),
			plumbing.NewHashReference(pr.ref, pr.old),
		); err != nil {
			return fmt.Errorf("update checkpoint ref %s: %w", pr.ref, err)
		}
	}
	return nil
}

// unappliedAncestry walks first parents back from a checkpoint ref's tip and
// returns the commits that do not carry the OPF trailer, ancestor-first, plus
// the parent the deepest one keeps: the trailered commit the walk stopped at,
// or zero at a root. Checkpoint refs are a single-parent chain, so the first
// parent is the whole history.
func unappliedAncestry(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, plumbing.Hash, error) {
	var chain []*object.Commit
	base := plumbing.ZeroHash
	for h := tip; !h.IsZero(); {
		c, err := repo.CommitObject(h)
		if err != nil {
			return nil, plumbing.ZeroHash, fmt.Errorf("load commit %s: %w", h.String()[:7], err)
		}
		if trailers.HasOPFApplied(c.Message) {
			base = h
			break
		}
		chain = append(chain, c)
		if len(c.ParentHashes) == 0 {
			break
		}
		h = c.ParentHashes[0]
	}
	slices.Reverse(chain)
	return chain, base, nil
}

// Pre-push OPF rewrite for entire/checkpoints/v1.
//
// This is the ONLY production code path that runs the OPF-augmented
// redaction entry points. Post-commit condensation stays on the
// regex-only pipeline for predictable latency; OPF runs here, once per
// push, after the user opted in via settings.
package strategy

import (
	"context"
	"crypto/sha256"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"math"
	"os"
	"strconv"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
	"github.com/entireio/cli/redact"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/storage"
)

// assetsDirName mirrors paths.AssetsDirName, captured at package scope so the
// OPF tree walkers can reference it even where a local variable named `paths`
// shadows the paths package (collectTreeBlobs).
const assetsDirName = paths.AssetsDirName

// V1DivergedError: local entire/checkpoints/v1 has commits that aren't
// ancestors of the remote tip (force-push or another machine pushed).
// Rewriting under divergence would silently rebase rejected work, so
// we refuse.
type V1DivergedError struct {
	Local, Remote, MergeBase plumbing.Hash
}

func (e *V1DivergedError) Error() string {
	return fmt.Sprintf("entire/checkpoints/v1 has diverged from remote (local=%s remote=%s merge_base=%s); "+
		"fetch the remote and either reset entire/checkpoints/v1 to <remote>/entire/checkpoints/v1 "+
		"or run `entire doctor --recover-v1` before pushing",
		e.Local.String()[:7], e.Remote.String()[:7], e.MergeBase.String()[:7])
}

// BootstrapTooLargeError: more un-OPF'd commits to rewrite than the
// safety cap — a first push to a remote with no v1 yet, or a checkpoint
// ref whose un-trailered ancestry runs deep because OPF was enabled
// late. OPF inference is ~30s per commit, so unbounded bootstraps could
// take hours.
type BootstrapTooLargeError struct {
	Count, Limit int
}

func (e *BootstrapTooLargeError) Error() string {
	return fmt.Sprintf("OPF bootstrap would rewrite %d checkpoint commits "+
		"(limit %d). Set ENTIRE_OPF_BOOTSTRAP_LIMIT=<N> or =unlimited to override, "+
		"or push without OPF (ENTIRE_OPF=no git push) to bring the remote into sync first",
		e.Count, e.Limit)
}

// V1RefMovedError: another worktree advanced the local ref during our
// rewrite (CAS conflict). Orphan rewritten objects sit in .git/objects
// until git gc --prune; no manual cleanup needed.
type V1RefMovedError struct {
	Expected, Actual plumbing.Hash
}

func (e *V1RefMovedError) Error() string {
	return fmt.Sprintf("entire/checkpoints/v1 moved during OPF rewrite "+
		"(expected %s, found %s); another local worktree advanced the ref "+
		"mid-rewrite — re-run `git push` (no fetch needed; the move was local)",
		e.Expected.String()[:7], e.Actual.String()[:7])
}

// OPFRuntimeFailedError: the OPF circuit breaker tripped mid-rewrite.
// Some blobs were silently downgraded to regex-only; tagging those
// commits as Entire-OPF-Applied would be a privacy regression (future
// pushes would skip them while their content is regex-only). Abort
// before CAS so the user fixes their OPF install and retries.
//
// Cause carries the underlying batch error when there is one (the
// breaker-tripped-at-start construction has none) so the real failure
// survives into the pre-push abort message and errors.Is/As chains.
type OPFRuntimeFailedError struct {
	OPFCommand string
	Cause      error
}

func (e *OPFRuntimeFailedError) Error() string {
	msg := fmt.Sprintf("OPF runtime failed during pre-push rewrite (command=%q); "+
		"aborting push so regex-only content isn't tagged as OPF-applied. "+
		"Run `%s --help` to verify your OPF install, then retry. Or set "+
		"ENTIRE_OPF=no on the push to skip OPF for this push only.",
		e.OPFCommand, e.OPFCommand)
	if e.Cause != nil {
		msg += fmt.Sprintf(" (cause: %v)", e.Cause)
	}
	return msg
}

func (e *OPFRuntimeFailedError) Unwrap() error {
	return e.Cause
}

// OPFNoCategoriesError: OPF is enabled but the effective category set
// is empty (categories omitted, {}, or all-false), so the model scan
// cannot run. Proceeding would stamp Entire-OPF-Applied on commits OPF
// never saw, and later rewrites would skip them permanently — even
// after the user fixes the config. Abort the push with remediation
// instead. Two gates enforce this: the decision gate in prePush runs
// whenever OPF is enabled, with no knowledge of whether anything is
// unpushed, so a misconfigured repo aborts every push — including one
// with nothing to rewrite. The rewrite-level gate in
// RewriteUnpushedV1WithOPF sits after the no-work early returns and
// fires only when commits are unpushed; it deliberately aborts even a
// re-parent-only push (every unpushed commit already tagged) rather
// than poking a no-new-stamping hole through the invariant.
type OPFNoCategoriesError struct{}

func (e *OPFNoCategoriesError) Error() string {
	return "OpenAI Privacy Filter is enabled but no detection category is enabled, " +
		"so the model scan cannot run; aborting push so unscanned content isn't " +
		"tagged as OPF-applied. Enable at least one category (e.g. " +
		`"private_person": true) under redaction.openai_privacy_filter.categories ` +
		"in .entire/settings.json (or .entire/settings.local.json), set " +
		"enabled: false to push regex-only content, or set ENTIRE_OPF=no on the " +
		"push to skip OPF for this push only."
}

const (
	// bootstrapDefaultLimit caps first-push history rewrites. Picked
	// to bound worst-case wall-clock at ~50min @ 30s/commit.
	bootstrapDefaultLimit = 100
	bootstrapEnvVar       = "ENTIRE_OPF_BOOTSTRAP_LIMIT"
)

func resolveBootstrapLimit() int {
	v := strings.TrimSpace(os.Getenv(bootstrapEnvVar))
	switch {
	case v == "":
		return bootstrapDefaultLimit
	case strings.EqualFold(v, "unlimited"):
		return math.MaxInt
	}
	if n, err := strconv.Atoi(v); err == nil && n > 0 {
		return n
	}
	return bootstrapDefaultLimit
}

// OPFBatchTooLargeError: a single push has more prose-leaf content
// than ENTIRE_OPF_BATCH_LIMIT will allow OPF to chew through in one
// inference call. Pushing under the limit yields a single ~10-30s
// pause; without the cap, a 100MB-of-prose push could take an hour.
//
// The user-facing remediation is identical in shape to
// BootstrapTooLargeError: bump the limit, push without OPF, or break
// the push into smaller pieces.
type OPFBatchTooLargeError struct {
	LeafBytes int
	Limit     int
}

func (e *OPFBatchTooLargeError) Error() string {
	return fmt.Sprintf("OPF would run inference on %d prose-leaf bytes "+
		"(limit %d). Set ENTIRE_OPF_BATCH_LIMIT=<bytes> or =unlimited to override, "+
		"or push without OPF (ENTIRE_OPF=no git push) and let a smaller follow-up push run OPF",
		e.LeafBytes, e.Limit)
}

const (
	// batchDefaultLimit caps the cumulative prose-leaf bytes one push
	// will hand to OPF. 2 MB at ~5.4s/100KB ≈ ~110s of inference, on
	// the high end of what's acceptable as a single push pause but
	// generous enough that any realistic push fits.
	batchDefaultLimit = 2 * 1024 * 1024
	batchEnvVar       = "ENTIRE_OPF_BATCH_LIMIT"
)

func resolveBatchLimit() int {
	v := strings.TrimSpace(os.Getenv(batchEnvVar))
	switch {
	case v == "":
		return batchDefaultLimit
	case strings.EqualFold(v, "unlimited"):
		return math.MaxInt
	}
	if n, err := strconv.Atoi(v); err == nil && n > 0 {
		return n
	}
	return batchDefaultLimit
}

// scaleBatchLimit multiplies a batch-limit value by mult, saturating
// at math.MaxInt to avoid signed-overflow when the limit is "unlimited"
// (math.MaxInt) or a very large explicit value. Returns 0 if either
// operand is non-positive, so the caller can treat 0 as "no cap" too.
func scaleBatchLimit(limit, mult int) int {
	if limit <= 0 || mult <= 0 {
		return 0
	}
	if limit > math.MaxInt/mult {
		return math.MaxInt
	}
	return limit * mult
}

// OPFRawBytesTooLargeError: the cumulative raw blob bytes the
// collection pass loaded into memory exceeded the safety ceiling.
// Unlike the leaf-byte cap, this is about RAM headroom rather than
// inference wall-clock — a 200 MiB push of mostly-structural JSON has
// tiny leaf content but huge raw bytes, and would OOM the user's
// shell before the leaf-byte cap got a chance to fire.
//
// The raw ceiling is derived from ENTIRE_OPF_BATCH_LIMIT (raw =
// leaf × rawByteCapMultiplier) so a user bumping the leaf cap
// proportionally bumps the raw ceiling and doesn't need a second
// env var.
type OPFRawBytesTooLargeError struct {
	RawBytes int
	Limit    int
}

func (e *OPFRawBytesTooLargeError) Error() string {
	return fmt.Sprintf("OPF rewrite would buffer %d raw blob bytes across "+
		"all unpushed commits (limit %d, ~%d× the prose-leaf cap as a RAM ceiling). "+
		"Bump ENTIRE_OPF_BATCH_LIMIT (the raw ceiling scales with it) "+
		"or push without OPF (ENTIRE_OPF=no git push) and let a smaller "+
		"follow-up push run OPF",
		e.RawBytes, e.Limit, rawByteCapMultiplier)
}

// rawByteCapMultiplier ties the raw-byte RAM ceiling to the leaf-byte
// inference cap. 100× means: leaf cap 2 MiB → raw ceiling 200 MiB.
// Picked to comfortably exceed any realistic JSON-scaffolding ratio
// (a 10 MiB JSONL with 300 KB of leaves still fits) while preventing
// pathological RAM blowups (a 5 GiB pasted dump aborts before loading).
const rawByteCapMultiplier = 100

// RewriteUnpushedV1WithOPF re-redacts unpushed entire/checkpoints/v1
// commits with OPF, builds new commits carrying Entire-OPF-Applied:
// true, and CAS-updates the local ref. Idempotent: already-applied
// commits are re-parented without re-running OPF.
//
// Caller checks redact.OPFEnabled() and skips this when OPF is off.
// Returns one of {V1DivergedError, BootstrapTooLargeError,
// V1RefMovedError, OPFRuntimeFailedError, OPFNoCategoriesError,
// OPFBatchTooLargeError, OPFRawBytesTooLargeError} for
// privacy-critical failures — the pre-push hook propagates these so
// git push aborts.
func RewriteUnpushedV1WithOPF(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
	localTip, err := readV1Tip(repo, plumbing.NewBranchReferenceName(paths.MetadataBranchName))
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read local v1: %w", err)
	}
	if localTip.IsZero() {
		return plumbing.ZeroHash, nil // no checkpoints yet
	}
	remoteTip, err := resolveRemoteV1Tip(ctx, repo, target)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read remote v1: %w", err)
	}

	if !remoteTip.IsZero() {
		mergeBase, mbErr := computeMergeBase(repo, localTip, remoteTip)
		if mbErr != nil {
			return plumbing.ZeroHash, fmt.Errorf("compute merge-base: %w", mbErr)
		}
		if mergeBase != remoteTip {
			return plumbing.ZeroHash, &V1DivergedError{Local: localTip, Remote: remoteTip, MergeBase: mergeBase}
		}
	}

	unpushed, err := listUnpushedV1Commits(repo, localTip, remoteTip)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("list unpushed v1 commits: %w", err)
	}
	if len(unpushed) == 0 {
		return localTip, nil
	}
	if remoteTip.IsZero() {
		if limit := resolveBootstrapLimit(); len(unpushed) > limit {
			return plumbing.ZeroHash, &BootstrapTooLargeError{Count: len(unpushed), Limit: limit}
		}
	}

	// Fail-closed defense: enabled-with-no-categories means the model
	// scan can't run at all. The decision resolution in prePush already
	// rejects this state before any prompt; this second gate covers
	// direct callers and sits before the breaker check so the user gets
	// the config-specific remediation rather than OPFRuntimeFailedError's
	// "verify your OPF install".
	if redact.OPFMisconfiguredNoCategories() {
		return plumbing.ZeroHash, &OPFNoCategoriesError{}
	}

	// Fail-closed defense: if OPF is already broken at the start of
	// this push (an earlier process step tripped the breaker), abort
	// before tagging any commits as OPF-applied. Without this, the
	// per-blob fallback inside the no-OPF cases of BatchBytesWithPrivacyFilter
	// could let regex-only content slip out with the trailer attached.
	if redact.OPFBreakerTripped() {
		return plumbing.ZeroHash, &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand()}
	}

	// Pass 1: collect every redactable blob from every unpushed commit
	// that still needs OPF. Already-applied commits get re-parented
	// later without collecting (their tree stays as-is). We also track
	// each blob's source commit + tree path so we can route the redacted
	// bytes back during apply.
	type pendingCommit struct {
		commit *object.Commit
		// blobs and paths are parallel slices; len(paths)==len(blobs).
		// startIdx is this commit's offset into the global redacted slice.
		blobs    []redact.NamedBlob
		paths    []string
		startIdx int
	}
	var globalBlobs []redact.NamedBlob
	pendings := make([]pendingCommit, 0, len(unpushed))
	// Bound raw-bytes-in-memory incrementally so a pathological push
	// (e.g. 5 GiB of pasted dumps) aborts before exhausting the user's
	// shell RAM. The leaf-byte cap downstream is about inference cost;
	// this one is about memory ceiling and fires earlier. scaleBatchLimit
	// saturates at math.MaxInt so "unlimited" actually means unlimited
	// — without saturation, "unlimited" × 100 overflows int and the cap
	// trips on every push.
	rawCap := scaleBatchLimit(resolveBatchLimit(), rawByteCapMultiplier)
	var rawBytesSoFar int
	for _, c := range unpushed {
		pc := pendingCommit{commit: c}
		if !trailers.HasOPFApplied(c.Message) {
			tree, err := repo.TreeObject(c.TreeHash)
			if err != nil {
				return plumbing.ZeroHash, fmt.Errorf("load tree for %s: %w", c.Hash.String()[:7], err)
			}
			pc.startIdx = len(globalBlobs)
			// Whole-tree redaction: each v1 commit tree is cumulative, so the
			// newest commit can still carry older shards that were regex-only
			// before this rewrite. Redacting the whole tree for every unapplied
			// commit keeps the final rewritten tip from reintroducing an
			// un-OPF-redacted older shard. collect and apply walk the tree the
			// same way so the cached keys line up.
			if err := collectTreeBlobs(repo, tree, "", &pc.blobs, &pc.paths); err != nil {
				return plumbing.ZeroHash, fmt.Errorf("collect blobs %s: %w", c.Hash.String()[:7], err)
			}
			for _, b := range pc.blobs {
				rawBytesSoFar += len(b.Content)
			}
			if rawBytesSoFar > rawCap {
				return plumbing.ZeroHash, &OPFRawBytesTooLargeError{RawBytes: rawBytesSoFar, Limit: rawCap}
			}
			globalBlobs = append(globalBlobs, pc.blobs...)
		}
		pendings = append(pendings, pc)
	}

	// Pass 2: enforce the leaf-byte cap, then make exactly ONE OPF
	// shell-out for the whole push. The cap runs before the shell-out
	// so a too-large push fails fast with a clear remediation message.
	var globalRedacted [][]byte
	if len(globalBlobs) > 0 {
		leafBytes := redact.SumProseLeafBytes(globalBlobs)
		if limit := resolveBatchLimit(); leafBytes > limit {
			return plumbing.ZeroHash, &OPFBatchTooLargeError{LeafBytes: leafBytes, Limit: limit}
		}
		globalRedacted, err = redact.BatchBytesWithPrivacyFilter(ctx, globalBlobs)
		if err != nil {
			// Converge with the up-front gate: the misconfiguration
			// sentinel must surface config remediation, not "verify
			// your OPF install".
			if errors.Is(err, redact.ErrOPFNoEnabledCategories) {
				return plumbing.ZeroHash, &OPFNoCategoriesError{}
			}
			return plumbing.ZeroHash, &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand(), Cause: err}
		}
	}

	// Pass 3: rebuild each commit. For OPF-applied commits, this is
	// just a re-parent (no tree changes). For unapplied commits, the
	// per-commit redaction map routes cached bytes by tree path.
	parent := remoteTip
	for _, pc := range pendings {
		var redactedByPath map[string][]byte
		if len(pc.blobs) > 0 {
			redactedByPath = make(map[string][]byte, len(pc.blobs))
			for i, path := range pc.paths {
				redactedByPath[path] = globalRedacted[pc.startIdx+i]
			}
		}
		newHash, err := rebuildCheckpointCommit(ctx, repo, pc.commit, parent, redactedByPath)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("rebuild commit %s: %w", pc.commit.Hash.String()[:7], err)
		}
		parent = newHash
	}

	if err := atomicSetV1Ref(repo, localTip, parent); err != nil {
		return plumbing.ZeroHash, err
	}
	return parent, nil
}

func readV1Tip(repo *git.Repository, refName plumbing.ReferenceName) (plumbing.Hash, error) {
	ref, err := repo.Reference(refName, true)
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return plumbing.ZeroHash, nil
		}
		return plumbing.ZeroHash, fmt.Errorf("resolve ref %s: %w", refName, err)
	}
	return ref.Hash(), nil
}

// opfRewriteFetchTmpRef is the temp ref used to stage the URL-fetched
// remote v1 tip during OPF rewrite. Cleaned up at the end of each
// resolveRemoteV1Tip call so the tracking is invisible to the user.
const opfRewriteFetchTmpRef = FetchTmpRefPrefix + "opf-rewrite-v1"

// resolveRemoteV1Tip returns the hash of the remote's
// entire/checkpoints/v1 tip.
//
// Fetches the v1 ref from target into a temporary local ref so the
// rewrite compares against the current remote tip rather than a stale
// remote-tracking ref. target may be either a remote name (e.g. "origin")
// or a URL (checkpoint_remote configured). Fetching is especially important
// for URL-based remotes, which have no tracking refs locally; otherwise every
// push would re-redact the entire history as a "bootstrap."
//
// Returns ZeroHash with no error when the remote has no v1 yet (genuine
// bootstrap case). Fetch failures fall back to ZeroHash + a warning
// log; the rewrite then treats the push as bootstrap rather than
// blocking the user on a transient network issue.
func resolveRemoteV1Tip(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
	srcRef := "refs/heads/" + paths.MetadataBranchName
	worktreeRoot := ""
	if wt, wtErr := repo.Worktree(); wtErr == nil {
		worktreeRoot = wt.Filesystem().Root()
	}
	if err := fetchURLIntoTmpRef(ctx, worktreeRoot, target, srcRef, opfRewriteFetchTmpRef, "v1 for OPF rewrite", true, checkpointRemoteFetchTimeout); err != nil {
		if !remote.IsURL(target) {
			logging.Warn(ctx, "OPF rewrite: failed to fetch remote v1; using local remote-tracking ref",
				slog.String("remote", target),
				slog.String("error", err.Error()),
			)
			return readV1Tip(repo, plumbing.NewRemoteReferenceName(target, paths.MetadataBranchName))
		}
		logging.Warn(ctx, "OPF rewrite: failed to fetch remote v1 from URL; treating push as bootstrap",
			slog.String("error", err.Error()),
		)
		return plumbing.ZeroHash, nil
	}
	defer func() {
		if err := repo.Storer.RemoveReference(plumbing.ReferenceName(opfRewriteFetchTmpRef)); err != nil {
			logging.Debug(ctx, "OPF rewrite: failed to clean up temp ref",
				slog.String("error", err.Error()),
			)
		}
	}()
	ref, err := repo.Reference(plumbing.ReferenceName(opfRewriteFetchTmpRef), true)
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return plumbing.ZeroHash, nil
		}
		return plumbing.ZeroHash, fmt.Errorf("resolve fetched v1 ref: %w", err)
	}
	return ref.Hash(), nil
}

// computeMergeBase returns the merge-base commit hash. Multi-base
// (criss-cross) and unrelated-histories both return ZeroHash —
// caller treats those as diverged.
func computeMergeBase(repo *git.Repository, local, remote plumbing.Hash) (plumbing.Hash, error) {
	lc, err := repo.CommitObject(local)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("load local commit: %w", err)
	}
	rc, err := repo.CommitObject(remote)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("load remote commit: %w", err)
	}
	bases, err := lc.MergeBase(rc)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("merge-base: %w", err)
	}
	if len(bases) != 1 {
		return plumbing.ZeroHash, nil
	}
	return bases[0].Hash, nil
}

// listUnpushedV1Commits returns commits reachable from localTip but not
// remoteTip, in graph order (oldest-first). Graph order matters more
// than timestamp order — commits made in rapid succession can share
// Author.When; the parent chain is the unambiguous truth.
//
// Optimization: the caller (RewriteUnpushedV1WithOPF) has already
// validated that remoteTip is the unique merge-base of local and
// remote, which means v1 is linear and remoteTip is an ancestor of
// localTip. So walking back from localTip, the FIRST commit we hit
// whose hash equals remoteTip is the boundary — no need to pre-build
// a full remote-reachability set. This drops the cost from
// O(local + remote history) to O(unpushed) per call.
func listUnpushedV1Commits(repo *git.Repository, localTip, remoteTip plumbing.Hash) ([]*object.Commit, error) {
	iter, err := repo.Log(&git.LogOptions{From: localTip})
	if err != nil {
		return nil, fmt.Errorf("log local tip: %w", err)
	}
	defer iter.Close()

	var unpushed []*object.Commit
	if walkErr := iter.ForEach(func(c *object.Commit) error {
		if !remoteTip.IsZero() && c.Hash == remoteTip {
			return errStop
		}
		unpushed = append(unpushed, c)
		return nil
	}); walkErr != nil && !errors.Is(walkErr, errStop) {
		return nil, fmt.Errorf("walk local v1 history: %w", walkErr)
	}
	// reverse for oldest-first
	for i, j := 0, len(unpushed)-1; i < j; i, j = i+1, j-1 {
		unpushed[i], unpushed[j] = unpushed[j], unpushed[i]
	}
	return unpushed, nil
}

// rebuildCheckpointCommit re-parents the commit onto parent (backend-agnostic:
// the v1 chain passes the rewritten predecessor, a standalone checkpoint ref
// passes the commit's own original parent). Already-applied
// commits keep their tree (idempotent); unapplied commits get a tree
// rebuilt from redactedByPath (precomputed by the orchestrator's single
// OPF batch call) plus an Entire-OPF-Applied: true trailer.
//
// redactedByPath maps each redactable blob's full tree path (e.g.
// "ab/cd.../0/full.jsonl") to its OPF-redacted bytes. Only required for
// unapplied commits; pass nil for already-applied ones.
//
// Correctness note: each v1 commit tree is cumulative. During a multi-commit
// rewrite, the newest original commit can still contain older shards that were
// regex-only before this rewrite. The collect/apply walkers redact the whole
// tree for every unapplied commit so the final rewritten tip cannot
// reintroduce an older un-OPF-redacted shard.
func rebuildCheckpointCommit(ctx context.Context, repo *git.Repository, oldCommit *object.Commit, parent plumbing.Hash, redactedByPath map[string][]byte) (plumbing.Hash, error) {
	newTree := oldCommit.TreeHash
	if !trailers.HasOPFApplied(oldCommit.Message) {
		tree, err := repo.TreeObject(oldCommit.TreeHash)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("load tree: %w", err)
		}
		// Whole-tree redaction — see the collect pass in
		// RewriteUnpushedV1WithOPF for why we never scope to a single shard.
		newTree, err = rebuildTreeWithCachedRedaction(repo, tree, "", redactedByPath)
		if err != nil {
			return plumbing.ZeroHash, err
		}
	}

	parents := []plumbing.Hash{}
	if !parent.IsZero() {
		parents = append(parents, parent)
	}
	c := &object.Commit{
		Author:       oldCommit.Author,
		Committer:    oldCommit.Committer,
		Message:      trailers.AppendOPFAppliedTrailer(oldCommit.Message),
		TreeHash:     newTree,
		ParentHashes: parents,
	}
	// Sign the rewritten commit when commit signing is enabled, matching
	// every other commit-construction site in this package (common.go,
	// metadata_reconcile.go, push_common.go). Without this, a user who
	// has signed checkpoint commits would see the rewrite produce
	// unsigned commits — silently degrading their integrity story.
	checkpoint.SignCommitBestEffort(ctx, c)
	obj := repo.Storer.NewEncodedObject()
	if err := c.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("encode commit: %w", err)
	}
	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("store commit: %w", err)
	}
	return hash, nil
}

// isRedactableBlobName reports whether a file at the given name should
// flow through OPF. The policy is fail-closed: every regular file
// inside the shard is redacted EXCEPT content_hash.txt, which is
// recomputed against the new full.jsonl in a deferred pass.
//
// Why an open policy: a closed allowlist (.jsonl/.txt/.json only)
// would silently skip any future blob type that lands in a shard
// — .md prose, agent dumps, no-extension transcript blobs — and ship
// it verbatim with the Entire-OPF-Applied trailer attached. Inverting
// to "redact everything except the deferred file" means new types are
// covered by default; opting out requires an explicit code change.
//
// The batch redactor (redact.BatchBytesWithPrivacyFilter, via
// NamedBlob) handles arbitrary content: .jsonl/.json go through
// JSON-aware leaf redaction; anything else gets byte redaction over
// the raw content. The OPF has-space gate excludes binary blobs from
// paying inference cost.
func isRedactableBlobName(name string) bool {
	return name != paths.ContentHashFileName
}

// collectTreeBlobs walks the whole tree and appends every redactable
// blob's content + full tree path to the parallel output slices. It
// walks the entire tree (no shard scoping — see RewriteUnpushedV1WithOPF
// for why); rebuildTreeWithCachedRedaction applies the same walk so the
// cached keys line up.
//
// blobs[i] and paths[i] correspond: paths[i] is the full path within
// the tree (e.g. "ab/cd.../0/full.jsonl"), used later by the apply
// walker to find each blob's redacted bytes in the cached map.
func collectTreeBlobs(repo *git.Repository, tree *object.Tree, pathPrefix string, blobs *[]redact.NamedBlob, paths *[]string) error {
	for _, e := range tree.Entries {
		switch e.Mode {
		case filemode.Dir:
			// Externalized image assets are opaque binary lifted out of the
			// (already redaction-skipped) transcript; byte-redacting them would
			// only corrupt the images. Skip the whole subtree — symmetrically with
			// rebuildTreeWithCachedRedaction, which preserves it verbatim.
			if e.Name == assetsDirName {
				continue
			}
			subPath := e.Name
			if pathPrefix != "" {
				subPath = pathPrefix + "/" + e.Name
			}
			subTree, err := repo.TreeObject(e.Hash)
			if err != nil {
				return fmt.Errorf("load subtree %s/%s: %w", pathPrefix, e.Name, err)
			}
			if err := collectTreeBlobs(repo, subTree, subPath, blobs, paths); err != nil {
				return err
			}
		case filemode.Regular, filemode.Executable:
			if !isRedactableBlobName(e.Name) {
				continue
			}
			content, err := readBlob(repo, e.Hash)
			if err != nil {
				return fmt.Errorf("read blob %s/%s: %w", pathPrefix, e.Name, err)
			}
			fullPath := e.Name
			if pathPrefix != "" {
				fullPath = pathPrefix + "/" + e.Name
			}
			*blobs = append(*blobs, redact.NamedBlob{Name: e.Name, Content: content})
			*paths = append(*paths, fullPath)
		case filemode.Empty, filemode.Deprecated, filemode.Symlink, filemode.Submodule:
			// Non-blob/non-tree entries are not redactable blobs.
		}
	}
	return nil
}

// rebuildTreeWithCachedRedaction walks the whole tree and produces a new
// tree using the precomputed redactedByPath map for redactable blobs.
// content_hash.txt files are recomputed in a second pass against the
// new full.jsonl in the same directory.
//
// Path-specific behavior:
//   - content_hash.txt → SHA256 of the sibling full.jsonl's new bytes
//     (deferred; not redacted itself)
//   - everything else → bytes looked up in redactedByPath. The
//     fail-closed policy redacts ANY regular file except content_hash.txt,
//     not just a closed allowlist of suffixes — a future blob type
//     (.md prose, agent dumps, no-extension transcript blobs) is
//     covered by default rather than slipping through. The collect
//     pass (collectTreeBlobs) populated redactedByPath using the same
//     "everything except content_hash.txt" predicate so the keys
//     match.
//
// A redactable blob missing from redactedByPath is either a
// programmer error (collect-pass / apply-pass walks went out of sync)
// OR a concurrent storage mutation that changed the tree between
// passes; we abort the rewrite rather than silently shipping
// unredacted content with the OPF-applied trailer.
func rebuildTreeWithCachedRedaction(repo *git.Repository, tree *object.Tree, pathPrefix string, redactedByPath map[string][]byte) (plumbing.Hash, error) {
	entries := make([]object.TreeEntry, 0, len(tree.Entries))
	// deferredHashes records indexes of content_hash.txt entries we
	// need to recompute after the full.jsonl in the same dir is built.
	type deferred struct {
		idx       int
		entryName string
		entryMode filemode.FileMode
	}
	var deferredHashes []deferred
	var newFullJSONLHash plumbing.Hash

	for _, e := range tree.Entries {
		switch e.Mode {
		case filemode.Dir:
			// Preserve externalized image assets verbatim (see collectTreeBlobs):
			// they are opaque binary and carry no redactable text. Copying the
			// subtree hash keeps blobs byte-identical so restore still round-trips.
			if e.Name == assetsDirName {
				entries = append(entries, e)
				continue
			}
			subPath := e.Name
			if pathPrefix != "" {
				subPath = pathPrefix + "/" + e.Name
			}
			subTree, err := repo.TreeObject(e.Hash)
			if err != nil {
				return plumbing.ZeroHash, fmt.Errorf("load subtree %s/%s: %w", pathPrefix, e.Name, err)
			}
			newSub, err := rebuildTreeWithCachedRedaction(repo, subTree, subPath, redactedByPath)
			if err != nil {
				return plumbing.ZeroHash, err
			}
			entries = append(entries, object.TreeEntry{Name: e.Name, Mode: e.Mode, Hash: newSub})

		case filemode.Regular, filemode.Executable:
			switch e.Name {
			case paths.ContentHashFileName:
				deferredHashes = append(deferredHashes, deferred{idx: len(entries), entryName: e.Name, entryMode: e.Mode})
				entries = append(entries, e) // placeholder; fixed in second pass
			default:
				// Inverted policy: every regular file except
				// content_hash.txt expects redacted bytes from the
				// collect pass. A missing key means the collect pass
				// didn't visit this path — either the storage changed
				// between passes or the two walkers disagree on which
				// files to include. Fail-closed.
				fullPath := e.Name
				if pathPrefix != "" {
					fullPath = pathPrefix + "/" + e.Name
				}
				newBytes, ok := redactedByPath[fullPath]
				if !ok {
					return plumbing.ZeroHash, fmt.Errorf("redacted bytes missing for %s "+
						"(collect/apply walk drift or concurrent storage mutation)", fullPath)
				}
				newHash, err := checkpoint.CreateBlobFromContent(repo, newBytes)
				if err != nil {
					return plumbing.ZeroHash, fmt.Errorf("write redacted blob %s: %w", fullPath, err)
				}
				entries = append(entries, object.TreeEntry{Name: e.Name, Mode: e.Mode, Hash: newHash})
				if e.Name == paths.TranscriptFileName {
					newFullJSONLHash = newHash
				}
			}
		case filemode.Empty, filemode.Deprecated, filemode.Symlink, filemode.Submodule:
			entries = append(entries, e)
		}
	}

	for _, d := range deferredHashes {
		if newFullJSONLHash.IsZero() {
			continue // no transcript in this dir; keep original hash
		}
		jsonlBytes, err := readBlob(repo, newFullJSONLHash)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("read new transcript for content_hash: %w", err)
		}
		sum := sha256.Sum256(jsonlBytes)
		hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(fmt.Sprintf("sha256:%x", sum)))
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("write content_hash: %w", err)
		}
		entries[d.idx] = object.TreeEntry{Name: d.entryName, Mode: d.entryMode, Hash: hashBlob}
	}

	newTree := &object.Tree{Entries: entries}
	obj := repo.Storer.NewEncodedObject()
	if err := newTree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("encode tree: %w", err)
	}
	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("store tree: %w", err)
	}
	return hash, nil
}

func readBlob(repo *git.Repository, hash plumbing.Hash) ([]byte, error) {
	blob, err := repo.BlobObject(hash)
	if err != nil {
		return nil, fmt.Errorf("blob: %w", err)
	}
	r, err := blob.Reader()
	if err != nil {
		return nil, fmt.Errorf("blob reader: %w", err)
	}
	defer func() { _ = r.Close() }()
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("blob read: %w", err)
	}
	return data, nil
}

// atomicSetV1Ref CAS-updates the local v1 ref. A concrete
// ErrReferenceHasChanged from the storer means another worktree
// advanced the ref during our rewrite — return V1RefMovedError so the
// hook aborts the push. Other errors (I/O, packed-ref locks, storage
// bugs) get wrapped as-is so they aren't misreported as concurrency
// failures.
func atomicSetV1Ref(repo *git.Repository, expectedOld, newHash plumbing.Hash) error {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	err := repo.Storer.CheckAndSetReference(
		plumbing.NewHashReference(refName, newHash),
		plumbing.NewHashReference(refName, expectedOld),
	)
	if err == nil {
		return nil
	}
	if errors.Is(err, storage.ErrReferenceHasChanged) {
		actual := plumbing.ZeroHash
		if cur, refErr := repo.Reference(refName, true); refErr == nil {
			actual = cur.Hash()
		}
		return &V1RefMovedError{Expected: expectedOld, Actual: actual}
	}
	return fmt.Errorf("set v1 ref: %w", err)
}

package strategy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"strings"

	git "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	checkpointremote "github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/perf"
	"github.com/entireio/cli/redact"
)

// errOPFAbortedByUser is returned when the user chose Abort (or pressed
// Ctrl-C) at the OPF prompt. PrePush returns it verbatim; the hook
// command propagates the non-zero exit code so git push aborts.
var errOPFAbortedByUser = errors.New("OPF prompt aborted by user; push cancelled")

var opfPrePushProgressWriter io.Writer = os.Stderr

// PrePush is called by the git pre-push hook before pushing to a remote.
// It pushes each ref in refs.Push alongside the user's push.
//
// If a checkpoint_remote is configured in settings, checkpoint branches/refs
// are pushed to the derived URL instead of the user's push remote.
//
// Configuration options (stored in .entire/settings.json under strategy_options):
//   - push_sessions: false to disable automatic pushing of checkpoints
//   - checkpoint_remote: {"provider": "github", "repo": "org/repo"} to push to a separate repo
func (s *ManualCommitStrategy) PrePush(ctx context.Context, remote string) error {
	return s.prePush(ctx, remote, false)
}

// PrePushFromGitHook handles a push initiated by Git's pre-push hook. Unlike
// direct callers, it protects an empty user remote from receiving checkpoint
// metadata before the user's first normal branch is published.
func (s *ManualCommitStrategy) PrePushFromGitHook(ctx context.Context, remote string) error {
	return s.prePush(ctx, remote, true)
}

func (s *ManualCommitStrategy) prePush(ctx context.Context, remote string, protectFirstUserBranch bool) error {
	// This runs inside the user's `git push` pre-push hook. Every checkpoint
	// git subprocess spawned here (metadata fetch, policy sync, checkpoint
	// push and its recovery fetch) must fail fast rather than block on an
	// interactive SSH passphrase prompt — there is no way to answer it here and
	// it would hang the user's push. Foreground commands do not set this.
	//
	// BatchMode=yes suppresses passphrase/PIN prompts (including FIDO2
	// verify-required PIN entry). Touch-only security keys still work because
	// user-presence touch is not a terminal read. Users who need a PIN prompt
	// in this path should load the key into ssh-agent, or set an explicit
	// BatchMode=no via GIT_SSH_COMMAND / core.sshCommand (respected by the
	// non-interactive SSH helper).
	ctx = checkpointremote.WithNonInteractiveSSH(ctx)

	// Load settings once for remote resolution and push_sessions check.
	// Spanned because checkpoint-remote resolution can perform a one-time
	// network fetch of the metadata branch (fetchMetadataBranchIfMissing),
	// which is otherwise invisible in the pre-push trace.
	resolveCtx, resolveSpan := perf.Start(ctx, "resolve_push_settings")
	ps := resolvePushSettings(resolveCtx, remote)
	resolveSpan.End()

	if ps.pushDisabled {
		return nil
	}

	// Single-remote gate (ENT-1451): checkpoint data syncs only to the
	// elected checkpoint sync remote. A dedicated checkpoint_remote URL is
	// exempt — it is a dedicated metadata store addressed directly, not a
	// remote selected by this push. The gate must stay BELOW
	// resolvePushSettings: hasCheckpointURL is only known after resolution,
	// so hoisting the gate above it would break the exemption.
	//
	// Capture is two-phase, straddling this whole function. The proposal runs
	// before the gate so that the push which elects a remote by evidence (push
	// target agrees with the branch's declared push destination) is also the
	// first push to carry checkpoints there; the election is persisted only at
	// the delivery points below, once those checkpoints actually arrived.
	// Everything in between can still stop delivery, and the election is
	// permanent, so intent is not enough to move it. The hint below then speaks
	// only for what capture left gated — see hintGatedCheckpointSync.
	var pendingCapture string
	if !ps.hasCheckpointURL() {
		if pendingCaptureCheckpointSyncRemote(ctx, ps.remote) {
			pendingCapture = ps.remote
		}
		if !checkpointSyncAllowedForRemote(ctx, ps.remote, pendingCapture) {
			hintGatedCheckpointSync(ctx, ps.remote)
			return nil
		}
	}

	// git-refs primary: push the per-checkpoint refs recorded in the push queue
	// instead of the single v1 branch. Those refs live under refs/entire/, not
	// refs/heads/, so a forge can never pick them as a repository's default
	// branch — the empty-remote guard below is unnecessary for this backend.
	// (A configured git-branch mirror's v1 ref is not pushed here yet — mirror
	// push for downgrade safety is a later step.)
	if ps.primaryIsRefs {
		return s.prePushCheckpointRefs(ctx, ps, pendingCapture)
	}

	// git-branch primary: entire/checkpoints/v1 is a real refs/heads branch, so
	// on an otherwise-empty remote a forge like GitHub would select it as the
	// default. Defer publication until the user's own branch exists there.
	deferAutomaticCheckpointPush := protectFirstUserBranch && deferCheckpointPushOnEmptyRemote(ctx, ps)

	refs := checkpoint.ResolveRefs(ctx)
	repo, repoErr := OpenRepository(ctx)
	if repoErr != nil {
		logging.Warn(ctx, "checkpoint policy pre-push: failed to open repository; allowing checkpoint push",
			slog.String("error", repoErr.Error()),
		)
	} else {
		defer repo.Close()
		syncCheckpointPolicyForPrePush(ctx, repo, ps)
		if !checkpointPolicyAllowsGitHook(ctx, repo) {
			// Policy failures should skip checkpoint pushes, not abort the user's push.
			return nil
		}
	}

	// OPF pre-push rewrite: if OPF is configured, resolve the user's
	// decision (env > settings > prompt > non-TTY auto-run), then
	// re-redact unpushed v1 commits with OPF (producing the OPF-applied,
	// 9-layer pipeline) before pushing. Skipped entirely when OPF is off,
	// so the common-case fast path is unchanged.
	if redact.OPFEnabled() {
		decision, decisionErr := opfPrePushDecision(ctx)
		if decisionErr != nil {
			logging.Warn(ctx, "OPF pre-push decision failed; aborting push",
				slog.String("error", decisionErr.Error()),
			)
			return decisionErr
		}
		switch decision {
		case OPFAbort:
			return errOPFAbortedByUser
		case OPFSkip:
			// User opted out for this push (or settings/env say
			// "never"). Push regex-only (8-layer) content as-is.
			logging.Info(ctx, "OPF skipped for this push (user choice or settings)")
		case OPFRun:
			_, opfSpan := perf.Start(ctx, "opf_pre_push_rewrite")
			if repoErr != nil {
				opfSpan.RecordError(repoErr)
				opfSpan.End()
				logging.Warn(ctx, "OPF pre-push: failed to open repo; aborting push",
					slog.String("error", repoErr.Error()),
				)
				return repoErr
			}
			if _, rewriteErr := RewriteUnpushedV1WithOPF(ctx, repo, ps.pushTarget()); rewriteErr != nil {
				opfSpan.RecordError(rewriteErr)
				opfSpan.End()
				logging.Warn(ctx, "OPF pre-push rewrite failed; aborting push",
					slog.String("error", rewriteErr.Error()),
				)
				return rewriteErr
			}
			opfSpan.End()
		}
	}

	if deferAutomaticCheckpointPush {
		// Do this only after OPF has had a chance to rewrite v1: the outer
		// user push may explicitly include the metadata branch.
		logging.Info(ctx, "automatic checkpoint push deferred until the remote has a branch",
			slog.String("remote", ps.remote),
		)
		return nil
	}

	// Thread the span's context into the push so the network push and any
	// fetch+rebase recovery nest beneath it as child steps in the perf trace.
	pushCtx, pushCheckpointsSpan := perf.Start(ctx, "push_checkpoint_refs")
	// Capture needs checkpoint data CONFIRMED on this remote, so count what
	// landed rather than trusting the absence of an error: every ref that was due
	// has to deliver, and at least one has to actually do so. Delivery must come
	// from pushRefIfNeeded's delivered return and NOT from err, which is
	// fail-soft and nil even when the remote refused the ref.
	deliveredCount, anyFailed := 0, false
	for _, ref := range refs.Push {
		delivered, err := pushRefIfNeeded(pushCtx, ps.pushTarget(), ref)
		if err != nil {
			pushCheckpointsSpan.RecordError(err)
			pushCheckpointsSpan.End()
			return err
		}
		if delivered {
			deliveredCount++
		} else {
			anyFailed = true
		}
	}
	pushCheckpointsSpan.End()

	// Delivered: the election may now follow the push that carried it. A push that
	// carried nothing — an empty ref set, or a v1 ref that does not exist locally
	// yet — leaves the election alone. It is safe either way (nothing is stranded
	// when there was nothing to strand), but capturing would announce a move that
	// moved no data, which is the class of claim this whole path exists to stop
	// making. The next push that carries a checkpoint captures instead.
	if pendingCapture != "" && deliveredCount > 0 && !anyFailed {
		commitCapturedSyncRemote(ctx, pendingCapture)
	}

	cleanupPushedShadowBranches(ctx)
	return nil
}

// opfPrePushDecision resolves the user's OPF decision for this push (env >
// settings > prompt > non-TTY auto-run). Shared by both checkpoint backends so
// the precedence cannot drift between them.
func opfPrePushDecision(ctx context.Context) (OPFDecision, error) {
	cfg, _ := settings.Load(ctx) //nolint:errcheck // Load already failed at hook init; fall back to nil
	var opfCfg *settings.OPFSettings
	if cfg != nil && cfg.Redaction != nil {
		opfCfg = cfg.Redaction.OpenAIPrivacyFilter
	}
	return resolveOPFDecisionForPrePush(ctx, opfCfg, opfPrePushProgressWriter)
}

// runOPFForCheckpointRefs resolves the OPF decision and, when it says run,
// rewrites the queued checkpoint refs. It reports whether the flush may
// proceed: false means OPF failed or the user aborted, so the caller withholds
// the checkpoint push and leaves the refs queued.
func runOPFForCheckpointRefs(ctx context.Context, repo *git.Repository) bool {
	decision, err := opfPrePushDecision(ctx)
	if err != nil {
		warnOPFCheckpointRefsWithheld(ctx, err)
		return false
	}
	switch decision {
	case OPFAbort:
		warnOPFCheckpointRefsWithheld(ctx, errOPFAbortedByUser)
		return false
	case OPFSkip:
		// Explicit opt-out for this push: flush the 8-layer content as-is,
		// untagged — same as the v1 path.
		logging.Info(ctx, "OPF skipped for this push (user choice or settings)")
	case OPFRun:
		_, opfSpan := perf.Start(ctx, "opf_pre_push_rewrite_refs")
		defer opfSpan.End()
		if rewriteErr := RewriteQueuedCheckpointRefsWithOPF(ctx, repo); rewriteErr != nil {
			opfSpan.RecordError(rewriteErr)
			warnOPFCheckpointRefsWithheld(ctx, rewriteErr)
			return false
		}
	}
	return true
}

// warnOPFCheckpointRefsWithheld reports a withheld flush on both channels: the
// log for diagnosis, and the user's terminal so a silently un-synced checkpoint
// is never the first they hear of it.
func warnOPFCheckpointRefsWithheld(ctx context.Context, err error) {
	logging.Warn(ctx, "OPF pre-push failed; skipping checkpoint ref push, refs left queued",
		slog.String("error", err.Error()),
	)
	fmt.Fprintf(stderrWriter,
		"[entire] OPF did not run, so checkpoint refs were not pushed and stay queued for your next push: %v\n", err)
}

// deferCheckpointPushOnEmptyRemote reports whether publication of the git-branch
// v1 metadata should be held back because the push remote may be brand new.
//
// Hosting providers such as GitHub make the first branch pushed to an empty
// repository its default, so the pre-push hook must not publish
// entire/checkpoints/v1 ahead of the user's own first branch. The check is
// purely local: if a remote-tracking ref for this remote already exists
// (refs/remotes/<remote>/*), the remote has been fetched from or pushed to
// before and therefore already has at least one branch, so publishing cannot
// make our metadata the default. Otherwise defer — git records a
// remote-tracking ref after the first successful push, so the deferred metadata
// publishes on the next push.
//
// It deliberately performs no ls-remote/fetch. A network round trip on the
// pre-push path can trigger an SSH security-key touch prompt (and doing so per
// push URL would multiply those prompts), which is a poor pre-push UX. This is
// also why it uses only the remote git handed the hook rather than resolving
// every configured push URL.
//
// A separate checkpoint remote is exempt: it is a dedicated metadata store, not
// the repository the user pushes to.
func deferCheckpointPushOnEmptyRemote(ctx context.Context, ps pushSettings) bool {
	if ps.hasCheckpointURL() {
		return false
	}

	// The hazard only arises for a configured remote (the `git remote add
	// origin …` then first-push flow). Pushing straight to a bare URL hands that
	// URL to the hook as the remote arg, and git never records a
	// refs/remotes/<url>/* tracking ref for it — so a tracking-ref check would
	// defer the metadata forever. Publish for a non-configured (URL) target
	// rather than strand it; the first-branch scenario always uses a named
	// remote.
	if !isConfiguredRemote(ctx, ps.remote) {
		return false
	}

	// Known limitation, accepted for the no-network design: a tracking ref left
	// over from before a remote was deleted and recreated empty under the same
	// URL reads as "established", so v1 would publish to the now-empty remote.
	// Detecting that requires asking the remote — the network round trip we
	// deliberately avoid here. The scenario is rare and its default branch is
	// recoverable by resetting it on the forge.
	return !remoteHasTrackingRefs(ctx, ps.remote)
}

// isConfiguredRemote reports whether name is a configured git remote, as
// opposed to a bare URL that git passes through verbatim when a push targets a
// URL directly. Local and best-effort (reads config, no network); any error is
// treated as "not a configured remote".
func isConfiguredRemote(ctx context.Context, name string) bool {
	if name == "" {
		return false
	}
	return cachedIsConfiguredRemote(ctx, name, func() (bool, error) {
		cmd := exec.CommandContext(ctx, "git", "remote", "get-url", name)
		if worktreeRoot, ok := settings.WorktreeRoot(ctx); ok {
			cmd.Dir = worktreeRoot
		}
		err := cmd.Run()
		if err == nil {
			return true, nil
		}
		// git ran and said no: a real answer worth caching. git failing to run at
		// all says nothing about the remote, and memoizing that false would
		// fail-close checkpoint_push_remote for the rest of the process.
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return false, nil
		}
		return false, fmt.Errorf("probe remote %q: %w", name, err)
	})
}

// remoteHasTrackingRefs reports whether any refs/remotes/<remote>/* ref exists
// locally. Its presence means the remote has been fetched from or pushed to
// before and so already has at least one branch. Local-only and best-effort:
// any error is treated as "no tracking refs" so the caller fails safe (defers).
func remoteHasTrackingRefs(ctx context.Context, remote string) bool {
	if remote == "" {
		return false
	}
	cmd := exec.CommandContext(ctx, "git", "for-each-ref", "--count=1", "refs/remotes/"+remote+"/")
	out, err := cmd.Output()
	if err != nil {
		return false
	}
	return strings.TrimSpace(string(out)) != ""
}

// prePushCheckpointRefs drains the per-checkpoint push queue and batch-pushes the
// recorded refs fast-forward-only (git-refs primary; never a force push — a
// diverged ref is recovered via fetch+replay). Transient push failures are logged and
// swallowed — like the v1 path, they must not block the user's git push — and the
// refs stay queued for the next pre-push. When OPF is enabled the queued refs
// are re-redacted with it first (RewriteQueuedCheckpointRefsWithOPF).
//
// It honors the checkpoint policy exactly like the v1 path: the policy gates on
// checkpoint *format* compatibility (diverged from the remote, or an unsupported
// local format), which is independent of the storage backend, so a blocked
// policy skips the ref push (leaving refs queued) rather than pushing.
func (s *ManualCommitStrategy) prePushCheckpointRefs(ctx context.Context, ps pushSettings, pendingCapture string) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Warn(ctx, "git-refs pre-push: open repo failed; skipping checkpoint push",
			slog.String("error", err.Error()))
		return nil
	}
	defer repo.Close()

	// Refresh the checkpoint policy from the remote, then skip the ref push
	// (leaving refs queued) if the policy is diverged or the local format is
	// unsupported — same gate the v1 path uses.
	syncCheckpointPolicyForPrePush(ctx, repo, ps)
	if !checkpointPolicyAllowsGitHook(ctx, repo) {
		return nil
	}

	// OPF backend divergence: both paths fail closed, but this one does it
	// without blocking the user. The v1 path aborts the user's git push; here a
	// checkpoint-ref failure must never do that (see this function's doc), so
	// failing closed means withholding the flush — nothing un-OPF'd ships, the
	// refs stay queued, and the user's push proceeds.
	if redact.OPFEnabled() && !runOPFForCheckpointRefs(ctx, repo) {
		return nil
	}

	if flushed, err := flushCheckpointRefsQueue(ctx, repo, ps); err == nil {
		// Delivered, and only if something actually was: an empty queue pushed
		// nothing, so it must not move the election or announce that it had.
		if pendingCapture != "" && flushed > 0 {
			commitCapturedSyncRemote(ctx, pendingCapture)
		}
	} else {
		// Fail-soft: a checkpoint-ref push failure must never block the user's
		// git push. The refs stay queued for the next pre-push.
		logging.Warn(ctx, "git-refs pre-push: checkpoint ref push failed; refs left queued",
			slog.String("error", err.Error()))
	}

	cleanupPushedShadowBranches(ctx)
	return nil
}

// PushQueuedCheckpointRefs pushes any queued checkpoint refs to the configured
// checkpoint remote, surfacing errors (unlike the fail-soft pre-push path); the
// caller owns the repo. It returns the number of refs pushed and whether
// pushing is disabled in settings — a distinct signal from pushed==0 with
// pushing enabled (an empty queue), so callers can report the two accurately.
// Like the pre-push paths, a checkpoint policy that blocks pushing errors with
// the refs left queued. Currently used by the checkpoint migration command's
// opt-in "push now".
func PushQueuedCheckpointRefs(ctx context.Context, repo *git.Repository, remote string) (pushed int, pushDisabled bool, err error) {
	ps := resolvePushSettings(ctx, remote)
	if ps.pushDisabled {
		return 0, true, nil
	}
	syncCheckpointPolicyForPrePush(ctx, repo, ps)
	if !checkpointPolicyAllowsGitHook(ctx, repo) {
		return 0, false, errors.New("checkpoint policy does not allow pushing checkpoint refs; refs stay queued")
	}
	pushed, err = flushCheckpointRefsQueue(ctx, repo, ps)
	// Clean up even on a partial/failed flush: a diverged batch can push some
	// refs and still return an error, and the shadow branches for the refs that
	// *did* land must still be cleaned up — parity with the pre-push path, which
	// always runs cleanup after flush regardless of its error.
	cleanupPushedShadowBranches(ctx)
	return pushed, false, err
}

// flushCheckpointRefsQueue drains the push-discovery queue and batch-pushes the
// recorded refs fast-forward-only, recovering a diverged ref by fetch+replay and
// removing from the queue only the refs that land. It returns the number pushed.
//
// Shared by the git-refs pre-push path (which logs and ignores the error to
// never block the user's push) and the migration command's opt-in push (which
// surfaces it). Stale entries — refs no longer present locally — are pruned so
// they don't block the queue forever.
func flushCheckpointRefsQueue(ctx context.Context, repo *git.Repository, ps pushSettings) (int, error) {
	queue, err := checkpoint.PushQueueForRepo(ctx, repo)
	if err != nil {
		return 0, fmt.Errorf("resolve push queue: %w", err)
	}
	queued, err := queue.Drain()
	if err != nil {
		return 0, fmt.Errorf("drain push queue: %w", err)
	}
	if len(queued) == 0 {
		return 0, nil
	}

	pushCtx, pushSpan := perf.Start(ctx, "push_checkpoint_refs")
	defer pushSpan.End()

	existing, stale := partitionLocalRefs(repo, queued)
	if len(stale) > 0 {
		if err := queue.Remove(stale); err != nil {
			logging.Warn(ctx, "git-refs push: prune stale queue entries failed",
				slog.String("error", err.Error()))
		}
	}
	if len(existing) == 0 {
		return 0, nil
	}

	// Resolved here, not by the caller: it spawns `git remote get-url` and its
	// result is unused unless refs are actually pushed, so an ordinary push with
	// an empty queue must not pay for it — nor print the multi-URL warning.
	dest := resolveRefsPushDestination(pushCtx, ps)
	dest.warnIgnoredPushURLs(pushCtx)

	// Progress: pushing many refs over the network can take tens of seconds, so
	// surface it (matching the v1 path's "[entire] Pushing ..." line) instead of
	// leaving the user's git push apparently hung. Written to stderr, which git
	// shows during the pre-push hook.
	fmt.Fprintf(os.Stderr, "[entire] Pushing %d checkpoint ref(s) to %s...", len(existing), dest.display())
	stop := startProgressDots(os.Stderr)

	// Fast path: push all refs in one round-trip (fast-forward-only). If every
	// ref was up to date or fast-forwarded, we're done.
	batchErr := batchPushRefs(pushCtx, dest.target, existing)
	if batchErr == nil {
		stop(" done")
		if removeErr := queue.Remove(existing); removeErr != nil {
			logging.Warn(ctx, "git-refs push: clear pushed refs from queue failed",
				slog.String("error", removeErr.Error()))
		}
		return len(existing), nil
	}
	stop("")

	// Non-interactive SSH auth failures cannot be fixed by per-ref
	// fetch+replay. Surface the same actionable hint as the v1 doPushRef path
	// (issue #1523) instead of only logging to .entire/logs/.
	if nonInteractiveSSHAuthFailure(pushCtx, batchErr) {
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't push checkpoint refs: %v\n", batchErr)
		printNonInteractiveSSHAuthHint()
		if dest.checkpointRemote {
			printCheckpointRemoteHint(dest.target)
		}
		return 0, batchErr
	}

	// At least one ref was rejected — typically a non-fast-forward divergence
	// (the same checkpoint re-written on another machine). Retry per ref with
	// fetch+replay recovery, and remove from the queue only the refs that land
	// (a genuine cherry-pick conflict leaves that ref queued for a later push,
	// never force-overwriting the remote).
	// Deliberately names no cause: the batch fails on divergence, but just as
	// often on an unreachable or unauthorized destination. Telling a user with a
	// dead remote that their refs "diverged" — or were "rejected", which equally
	// implies the remote answered — sends them after the wrong problem.
	fmt.Fprintf(os.Stderr, "[entire] Checkpoint ref push failed; retrying %d ref(s) individually...", len(existing))
	stop = startProgressDots(os.Stderr)
	pushed := make([]plumbing.ReferenceName, 0, len(existing))
	var firstErr error
	for _, ref := range existing {
		if err := pushCheckpointRefWithRecovery(pushCtx, dest.target, ref); err != nil {
			logging.Warn(ctx, "git-refs push: checkpoint ref push/sync failed; left queued, not overwritten",
				slog.String("ref", ref.String()), slog.String("error", err.Error()))
			if nonInteractiveSSHAuthFailure(pushCtx, err) {
				printNonInteractiveSSHAuthHint()
			}
			if firstErr == nil {
				firstErr = err
			}
			continue
		}
		pushed = append(pushed, ref)
	}
	stop(fmt.Sprintf(" pushed %d of %d", len(pushed), len(existing)))
	if err := queue.Remove(pushed); err != nil {
		logging.Warn(ctx, "git-refs push: clear pushed refs from queue failed",
			slog.String("error", err.Error()))
	}
	if firstErr != nil {
		return len(pushed), fmt.Errorf("%d of %d checkpoint refs failed to push: %w",
			len(existing)-len(pushed), len(existing), firstErr)
	}
	return len(pushed), nil
}

// cleanupPushedShadowBranches runs post-push shadow-branch cleanup. Failures are
// non-fatal — shadow branches just accumulate until `entire clean` or the next
// successful push.
func cleanupPushedShadowBranches(ctx context.Context) {
	if deleted, cleanupErr := CleanupPushedShadowBranches(ctx); cleanupErr != nil {
		logging.Warn(ctx, "post-push shadow branch cleanup failed",
			slog.String("error", cleanupErr.Error()),
		)
	} else if deleted > 0 {
		logging.Info(ctx, "cleaned up vestigial shadow branches",
			slog.Int("count", deleted),
		)
	}
}

