89	// (duplicate enqueues of the same ref, or malformed/blank lines), Drain rewrites
90	// it to the de-duplicated set. Enqueue only ever appends, so without this the
91	// file would grow unboundedly between the Removes that are otherwise the sole
92	// compaction point (e.g. a long-lived session that keeps re-enqueuing the same
93	// checkpoint ref but never pushes).
94	func (q *PushQueue) Drain() ([]plumbing.ReferenceName, error) {
95		release, err := flock.Acquire(q.lockPath())
96		if err != nil {
97			return nil, fmt.Errorf("lock push queue: %w", err)
98		}
99		defer release()
100	
101		refs, rawLines, err := q.readLocked()
102		if err != nil {
103			return nil, err
104		}
105		if rawLines > len(refs) {
106			if err := q.rewriteLocked(refs); err != nil {
107				return nil, err
108			}
109		}
110		return refs, nil
111	}
112	
113	// Peek returns the de-duplicated refs currently queued, in first-seen order,
114	// without mutating the queue file. Read-only counterpart to Drain (which
115	// compacts redundant lines in place) — for counters/status displays that must
116	// observe the queue without owning a push. A missing queue file yields no refs.
117	func (q *PushQueue) Peek() ([]plumbing.ReferenceName, error) {
118		release, err := flock.Acquire(q.lockPath())
119		if err != nil {
120			return nil, fmt.Errorf("lock push queue: %w", err)
121		}
122		defer release()
123	
124		refs, _, err := q.readLocked()
