128	// Remove deletes the given refs from the queue, preserving any entries appended
129	// after a Drain (e.g. a write that landed during the push). Called after a
130	// confirmed push.
131	func (q *PushQueue) Remove(refs []plumbing.ReferenceName) error {
132		if len(refs) == 0 {
133			return nil
134		}
135		release, err := flock.Acquire(q.lockPath())
136		if err != nil {
137			return fmt.Errorf("lock push queue: %w", err)
138		}
139		defer release()
140	
141		current, _, err := q.readLocked()
142		if err != nil {
143			return err
144		}
145		removed := make(map[string]struct{}, len(refs))
146		for _, r := range refs {
147			removed[r.String()] = struct{}{}
148		}
149		kept := make([]plumbing.ReferenceName, 0, len(current))
150		for _, r := range current {
151			if _, drop := removed[r.String()]; drop {
152				continue
153			}
154			kept = append(kept, r)
155		}
156		return q.rewriteLocked(kept)
157	}
