159	// rewriteLocked replaces the queue file with exactly refs (de-duplicated, one
160	// line each), or removes the file when refs is empty so a clean repo has no
161	// stray queue. The caller must hold the lock. The write is atomic (temp file +
162	// rename) so a concurrent reader never sees a half-written queue.
163	func (q *PushQueue) rewriteLocked(refs []plumbing.ReferenceName) error {
164		if len(refs) == 0 {
165			if err := os.Remove(q.queuePath()); err != nil && !os.IsNotExist(err) {
166				return fmt.Errorf("remove empty push queue: %w", err)
167			}
168			return nil
169		}
170		var buf bytes.Buffer
171		for _, r := range refs {
172			line, err := json.Marshal(pushQueueEntry{Ref: r.String()})
173			if err != nil {
174				return fmt.Errorf("encode push queue entry: %w", err)
175			}
176			buf.Write(line)
177			buf.WriteByte('\n')
178		}
179		if err := writeFileAtomicInDir(q.dir, q.queuePath(), buf.Bytes()); err != nil {
180			return fmt.Errorf("rewrite push queue: %w", err)
181		}
182		return nil
183	}
