186	// order. The caller must hold the lock. Malformed lines are skipped rather than
187	// failing the whole drain — a single bad record must not strand every queued ref.
188	//
189	// rawLines is the number of non-empty lines seen (including duplicates and
190	// malformed records), so callers can detect when the file holds more than the
191	// de-duplicated set and is worth compacting: rawLines > len(refs) exactly when
192	// there were redundant lines.
193	func (q *PushQueue) readLocked() (refs []plumbing.ReferenceName, rawLines int, err error) {
194		f, err := os.Open(q.queuePath())
195		if err != nil {
196			if os.IsNotExist(err) {
197				return nil, 0, nil
198			}
199			return nil, 0, fmt.Errorf("open push queue: %w", err)
200		}
201		defer f.Close()
202	
203		seen := make(map[string]struct{})
204		scanner := bufio.NewScanner(f)
205		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
206		for scanner.Scan() {
207			line := bytes.TrimSpace(scanner.Bytes())
