220			refs = append(refs, plumbing.ReferenceName(entry.Ref))
221		}
222		if err := scanner.Err(); err != nil {
223			return nil, 0, fmt.Errorf("read push queue: %w", err)
224		}
225		return refs, rawLines, nil
226	}
227	
228	// writeFileAtomicInDir writes data to a temp file in dir and renames it over
229	// path, so a reader (under the lock) never sees a half-written queue.
