240		}
241		if err := tmp.Close(); err != nil {
242			return fmt.Errorf("close temp push queue: %w", err)
243		}
244		if err := os.Rename(tmpName, path); err != nil {
245			return fmt.Errorf("rename temp push queue: %w", err)
