42	// prompt_default before the failure surfaces. Explicit skips (env no,
43	// prompt_default never) still resolve to OPFSkip: they push regex-only
44	// content without the trailer, which is an honest opt-out.
45	//
46	// Pure logic — prompter is only called when the user needs to decide.
47	// Tests inject a fake.
48	func resolveOPFDecision(env, promptDefault string, hasTTY, misconfigured bool, prompter func() (OPFDecision, error)) (OPFDecision, error) {
49		failClosedOr := func(d OPFDecision) (OPFDecision, error) {
50			if misconfigured {
51				return OPFAbort, &OPFNoCategoriesError{}
52			}
53			return d, nil
54		}
55		switch strings.ToLower(strings.TrimSpace(env)) {
56		case "yes":
57			return failClosedOr(OPFRun)
58		case "no":
59			return OPFSkip, nil
60		}
61		switch strings.ToLower(strings.TrimSpace(promptDefault)) {
62		case settings.OPFPromptNever:
63			return OPFSkip, nil
64		case settings.OPFPromptAlways:
65			return failClosedOr(OPFRun)
66		}
67		if !hasTTY {
68			// Non-interactive context: run OPF (matches the user's "if
69			// enabled, just run" preference). The caller emits a progress
70			// line at run time so scripted output isn't silent.
71			return failClosedOr(OPFRun)
72		}
73		if misconfigured {
74			return OPFAbort, &OPFNoCategoriesError{}
75		}
