80	// settings + TTY, calls askOPFPrompt when interactive, emits a stderr
81	// progress line on the non-TTY auto-run path. errOut receives the
82	// progress line (only printed when we'll actually run + the caller is
83	// non-interactive).
84	func resolveOPFDecisionForPrePush(ctx context.Context, opf *settings.OPFSettings, errOut io.Writer) (OPFDecision, error) {
85		hasTTY := interactive.CanPromptInteractively()
86		promptDefault := ""
