94			redact.OPFMisconfiguredNoCategories(),
95			func() (OPFDecision, error) { return askOPFPrompt(ctx) },
96		)
97		if err != nil {
98			return OPFAbort, err
99		}
100		if d == OPFRun && !hasTTY {
101			fmt.Fprintln(errOut, "→ OpenAI Privacy Filter: scanning checkpoints before push (may take ~30s)…")
102		}
103		return d, nil
104	}
