107	// OPFAbort. Selecting "Always" persists prompt_default=always to
108	// .entire/settings.local.json so future pushes don't ask.
109	//
110	// Style matches other entire CLI prompts via uiform.New, which applies the
111	// shared base16 palette theme and accessibility handling (the same wiring
112	// cli.NewAccessibleForm uses). uiform is a leaf package, so strategy can
113	// import it without the cycle that importing cli would create.
114	func askOPFPrompt(ctx context.Context) (OPFDecision, error) {
115		const (
116			choiceYes    = "yes"
117			choiceNo     = "no"
118			choiceAlways = "always"
119		)
120		choice := choiceYes
121		form := uiform.New(
122			huh.NewGroup(
123				huh.NewSelect[string]().
124					Title("Run OpenAI Privacy Filter on these checkpoints?").
125					Description("Adds ~30s but redacts names/PII the regex layers can't catch. Ctrl-C to cancel the push.").
126					Options(
127						huh.NewOption("Yes — run OPF this push", choiceYes),
128						huh.NewOption("No — skip OPF, push as-is", choiceNo),
129						huh.NewOption("Always — run OPF on every push from now on", choiceAlways),
130					).
131					Value(&choice),
132			),
133		)
134		if err := form.RunWithContext(ctx); err != nil {
135			if errors.Is(err, huh.ErrUserAborted) {
136				return OPFAbort, nil
137			}
138			return OPFAbort, fmt.Errorf("opf prompt: %w", err)
139		}
140		if choice == choiceAlways {
141			if err := persistOPFPromptDefaultAlways(ctx); err != nil {
142				logging.Warn(ctx, "failed to persist OPF prompt_default=always",
143					slog.String("error", err.Error()))
144			}
145		}
146		if choice == choiceNo {
147			return OPFSkip, nil
148		}
149		return OPFRun, nil
150	}
