153	// redaction.openai_privacy_filter.prompt_default = "always" to
154	// .entire/settings.local.json, preserving any unrelated fields by
155	// using a generic JSON-map round-trip.
156	func persistOPFPromptDefaultAlways(ctx context.Context) error {
157		path, raw, _, err := settings.LoadLocalRaw(ctx)
158		if err != nil {
159			return fmt.Errorf("load local settings: %w", err)
160		}
161		if raw == nil {
162			raw = map[string]json.RawMessage{}
163		}
164		redactionRaw := readSubObject(ctx, raw, "redaction")
165		opfRaw := readSubObject(ctx, redactionRaw, "openai_privacy_filter")
166	
