174			return err
175		}
176		if err := writeSubObject(raw, "redaction", redactionRaw); err != nil {
177			return err
178		}
179		if err := settings.SaveLocalRaw(path, raw); err != nil {
180			return fmt.Errorf("save local settings: %w", err)
181		}
182		return nil
183	}
184	
185	func readSubObject(ctx context.Context, parent map[string]json.RawMessage, key string) map[string]json.RawMessage {
186		sub := map[string]json.RawMessage{}
187		data, ok := parent[key]
188		if !ok {
