200	}
201	
202	func writeSubObject(parent map[string]json.RawMessage, key string, sub map[string]json.RawMessage) error {
203		data, err := json.Marshal(sub)
204		if err != nil {
205			return fmt.Errorf("marshal %s: %w", key, err)
206		}
207		parent[key] = data
208		return nil
209	}
